class Solution:
    def numRabbits(self, answers: List[int]) -> int:
        open_slots = {}
        total = 0
        for x in answers:
            if open_slots.get(x, 0) > 0:
                open_slots[x] -= 1
            else:
                total += x + 1
                open_slots[x] = x
        return total

