class Solution {
public:
    int numRabbits(vector<int>& answers) {
        unordered_map<int,int> openSlots;
        int total = 0;
        for (int x : answers) {
            auto it = openSlots.find(x);
            if (it != openSlots.end() && it->second > 0) {
                it->second--;
            } else {
                total += x + 1;
                openSlots[x] = x;
            }
        }
        return total;
    }
};

