class Solution {
    public int numRabbits(int[] answers) {
        Map<Integer, Integer> openSlots = new HashMap<>();
        int total = 0;
        for (int x : answers) {
            int left = openSlots.getOrDefault(x, 0);
            if (left > 0) {
                openSlots.put(x, left - 1);
            } else {
                total += x + 1;
                openSlots.put(x, x);
            }
        }
        return total;
    }
}

