class Solution {
    public int numRabbits(int[] answers) {
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int x : answers) cnt.merge(x, 1, Integer::sum);
        int total = 0;
        for (Map.Entry<Integer, Integer> e : cnt.entrySet()) {
            int x = e.getKey(), c = e.getValue();
            total += (c + x) / (x + 1) * (x + 1);
        }
        return total;
    }
}

